import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.z3u3TMv0.js";const m=JSON.parse('{"title":"生图模型部署","description":"不会云端生图 API 时，在电脑上部署 A1111 或 ComfyUI，再用 MiniTavern 局域网生图。","frontmatter":{"title":"生图模型部署","description":"不会云端生图 API 时，在电脑上部署 A1111 或 ComfyUI，再用 MiniTavern 局域网生图。","head":[["meta",{"name":"keywords","content":"酒馆,AI酒馆,Ai酒馆,迷你酒馆,超迷你酒馆,MiniTavern,AI伙伴,AI朋友,Ai本地聊天,AI本地聊天,Silly Tavern,SillyTavern,手机玩Silly Tavern,Silly Tavern手机版,Silly Tavern安卓,Silly Tavern苹果,AI角色扮演,角色卡,角色扮演,AI聊天,手机AI,离线AI,AI剧情,本地大模型,本地模型,Ollama,LM Studio,世界书,正则,BYOK,用户手册,教程,character card,AI roleplay,AI companion,tavern AI"}],["meta",{"property":"og:title","content":"生图模型部署 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"不会云端生图 API 时，在电脑上部署 A1111 或 ComfyUI，再用 MiniTavern 局域网生图。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/local/image-gen"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/local/image-gen"}]]},"headers":[],"relativePath":"local/image-gen/index.md","filePath":"local/image-gen/index.md","lastUpdated":1786517442000}'),i={name:"local/image-gen/index.md"};function n(d,t,l,c,h,s){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="生图模型部署" tabindex="-1">生图模型部署 <a class="header-anchor" href="#生图模型部署" aria-label="Permalink to &quot;生图模型部署&quot;">​</a></h1><p>MiniTavern 支持云端生图（OpenAI / Gemini / OpenRouter / Qwen）与<strong>本机</strong> Stable Diffusion 系服务：</p><table tabindex="0"><thead><tr><th>本机后端</th><th>App 平台</th><th>默认端口</th></tr></thead><tbody><tr><td><a href="./a1111">AUTOMATIC1111 / SD WebUI</a></td><td>A1111(SD WebUI)</td><td><code>7860</code></td></tr><tr><td><a href="./comfyui">ComfyUI</a></td><td>ComfyUI</td><td><code>8188</code>（Desktop 常见 <code>8000</code>）</td></tr></tbody></table><p>手机上的 MiniTavern <strong>不在手机里跑</strong>扩散模型；图在电脑（或云 GPU）生成，App 只发请求并展示结果。</p><h2 id="你需要什么" tabindex="-1">你需要什么 <a class="header-anchor" href="#你需要什么" aria-label="Permalink to &quot;你需要什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>建议</th></tr></thead><tbody><tr><td>电脑</td><td>Windows 最省事；macOS / Linux 也可</td></tr><tr><td>显卡</td><td><strong>NVIDIA 6GB+</strong> 较舒适（SD 1.5）；SDXL / 较大模型建议 <strong>8–12GB+</strong></td></tr><tr><td>无独显</td><td>可试 CPU（很慢）或租用云 GPU（按小时计费，非免费）</td></tr><tr><td>网络</td><td>手机与电脑同一 Wi‑Fi（勿用访客隔离网）</td></tr><tr><td>磁盘</td><td>模型文件常 <strong>2–10GB+</strong> / 个，预留空间</td></tr></tbody></table><p>没有 GPU、也不想部署时：可用 <a href="/ultra_guides/free-cloud/#免费生图怎么配">免费云端 · 生图</a> 里的云端免费图像档（若有），或暂只聊天不生图。</p><h2 id="选哪条路径" tabindex="-1">选哪条路径 <a class="header-anchor" href="#选哪条路径" aria-label="Permalink to &quot;选哪条路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>适合谁</th><th>难度</th></tr></thead><tbody><tr><td><a href="./a1111">A1111</a></td><td>想要传统 WebUI、参数直观、与酒馆生态常见对接</td><td>中</td></tr><tr><td><a href="./comfyui">ComfyUI</a></td><td>想要工作流 / 新模型支持快；App 使用内置默认 workflow</td><td>中</td></tr></tbody></table><p>两条路径最后都要：<a href="./connect-app">在 MiniTavern 中配置生图连接</a>。</p><h2 id="推荐阅读顺序" tabindex="-1">推荐阅读顺序 <a class="header-anchor" href="#推荐阅读顺序" aria-label="Permalink to &quot;推荐阅读顺序&quot;">​</a></h2><ol><li>按硬件选 <a href="./a1111">A1111</a> 或 <a href="./comfyui">ComfyUI</a> 完成安装与下载模型</li><li>开启 <strong>API + 局域网监听</strong>（各教程内有说明）</li><li><a href="./connect-app">连接 MiniTavern</a> 并测连</li><li>在聊天里用 <code>/imagine</code> 或附件 → 生图（见 <a href="/ultra_guides/manual/model-link#生图连接--智能--关键词">模型连接 · 生图</a>）</li><li>返回 <a href="/ultra_guides/local/">部署本地模型</a> 总览</li></ol><h2 id="重要提醒" tabindex="-1">重要提醒 <a class="header-anchor" href="#重要提醒" aria-label="Permalink to &quot;重要提醒&quot;">​</a></h2><ul><li>手机里填的地址必须是电脑的 <strong>局域网 IP</strong>（如 <code>192.168.1.8</code>），<strong>不要</strong>填 <code>localhost</code> / <code>127.0.0.1</code>。</li><li>A1111 必须带 <strong><code>--api</code></strong>；仅开 Web 界面不够。</li><li>ComfyUI 需 <strong><code>--listen</code></strong>（或 Desktop 里 Listen 设为 <code>0.0.0.0</code>）才能被手机访问。</li><li>防火墙放行对应端口；不要把未鉴权的生图 API 暴露到公网。</li><li>当前 App 的 Comfy 默认工作流<strong>不消费参考图</strong>；需要锁脸时优先 A1111 或云端支持参考图的平台。</li></ul>',14)])])}const g=e(i,[["render",n]]);export{m as __pageData,g as default};
